-- 10.62.0 — Universal Data Entry & Catalog Convergence
CREATE TABLE IF NOT EXISTS platform_reusable_sectors (code TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_reusable_languages (code TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_reusable_currencies (code TEXT PRIMARY KEY,name TEXT NOT NULL,symbol TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_reusable_regions (code TEXT PRIMARY KEY,name TEXT NOT NULL,country_code TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_reusable_classifications (code TEXT PRIMARY KEY,name TEXT NOT NULL,domain TEXT NOT NULL DEFAULT 'general',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_reusable_policies (code TEXT PRIMARY KEY,name TEXT NOT NULL,policy_type TEXT NOT NULL,scope TEXT NOT NULL DEFAULT 'platform',configuration_json TEXT NOT NULL DEFAULT '{}',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_reusable_responsibilities (code TEXT PRIMARY KEY,name TEXT NOT NULL,role_code TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_code) REFERENCES organization_role_catalog(role_code));
CREATE TABLE IF NOT EXISTS platform_storage_registry (code TEXT PRIMARY KEY,name TEXT NOT NULL,provider_code TEXT NOT NULL,region_code TEXT,purpose TEXT NOT NULL DEFAULT 'general',residency_mode TEXT NOT NULL DEFAULT 'policy',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(provider_code) REFERENCES external_provider_registry(code));
CREATE TABLE IF NOT EXISTS platform_reusable_pages (id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,page_type TEXT NOT NULL DEFAULT 'content',language_code TEXT NOT NULL DEFAULT 'en',country_code TEXT,body TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(country_code) REFERENCES platform_product_country_catalog(code));
CREATE TABLE IF NOT EXISTS platform_reusable_features (code TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_reusable_guidance (code TEXT PRIMARY KEY,name TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',language_code TEXT NOT NULL DEFAULT 'en',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_reusable_eligibility (code TEXT PRIMARY KEY,name TEXT NOT NULL,rule_json TEXT NOT NULL DEFAULT '{}',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_reusable_pricing (code TEXT PRIMARY KEY,name TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'EUR',price_minor INTEGER NOT NULL DEFAULT 0,billing_interval TEXT NOT NULL DEFAULT 'month',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_platform_reusable_pages_country ON platform_reusable_pages(country_code,status);
CREATE INDEX IF NOT EXISTS idx_platform_reusable_pages_language ON platform_reusable_pages(language_code,status);
CREATE INDEX IF NOT EXISTS idx_platform_storage_provider ON platform_storage_registry(provider_code,active);
CREATE INDEX IF NOT EXISTS idx_platform_responsibilities_role ON platform_reusable_responsibilities(role_code,active);
